definition.script:
// Configuration
var token = input.get("accessToken");
var groupName = input.get("groupName");
var selectFields = input.get("selectFields") || "";

// Validate inputs
if (!token) {
    log.error("Access token is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Access token is required");
    tags.trigger("error");
} else if (!groupName) {
    log.error("Group name is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Group name is required");
    tags.trigger("error");
} else {
    // Build URL with OData filter
    var filter = "displayName eq '" + groupName.replace(/'/g, "''") + "'";
    var url = "https://graph.microsoft.com/v1.0/groups?$filter=" + encodeURIComponent(filter);
    if (selectFields) {
        url += "&$select=" + selectFields;
    }

    // Headers for Graph API
    var headers = {
        "Authorization": "Bearer " + token,
        "Accept": "application/json",
        "ConsistencyLevel": "eventual"
    };

    log.info("Searching for group: " + groupName);

    try {
        var response = http.get(url, headers);

        if (!response.isSuccess) {
            log.error("API error: HTTP " + response.statusCode);
            output.set("Group", null);
            output.set("GroupJson", "");
            output.set("Found", false);
            output.set("HasErrors", true);
            output.set("ErrorMessage", "API error: HTTP " + response.statusCode);
            tags.trigger("error");
        } else {
            var data = json.parse(response.body);

            if (data && data.value && data.value.length > 0) {
                var group = data.value[0];
                log.info("Found group: " + group.displayName + " (ID: " + group.id + ")");

                output.set("Group", group);
                output.setJson("GroupJson", group);
                output.set("Found", true);
                output.set("MatchCount", data.value.length);
                output.set("GroupId", group.id || "");
                output.set("DisplayName", group.displayName || "");
                output.set("MailNickname", group.mailNickname || "");
                output.set("SecurityEnabled", group.securityEnabled || false);
                output.set("MailEnabled", group.mailEnabled || false);
                output.set("HasErrors", false);
                output.set("ErrorMessage", "");
                tags.trigger("success");
            } else {
                log.warn("Group not found: " + groupName);
                output.set("Group", null);
                output.set("GroupJson", "");
                output.set("Found", false);
                output.set("MatchCount", 0);
                output.set("GroupId", "");
                output.set("DisplayName", "");
                output.set("MailNickname", "");
                output.set("SecurityEnabled", false);
                output.set("MailEnabled", false);
                output.set("HasErrors", false);
                output.set("ErrorMessage", "");
                tags.trigger("notfound");
            }
        }

    } catch (ex) {
        log.error("Exception: " + ex.message);
        output.set("Group", null);
        output.set("GroupJson", "");
        output.set("Found", false);
        output.set("HasErrors", true);
        output.set("ErrorMessage", "Exception: " + ex.message);
        tags.trigger("error");
    }
}
